function ss_cfg($name,$default=''){ if(defined($name)) return constant($name); $v=getenv($name); return ($v!==false&&$v!=='')?$v:$default; }
$DB_HOST=ss_cfg('SKILLSNAP_DB_HOST','localhost');
$DB_NAME=ss_cfg('SKILLSNAP_DB_NAME','');
$DB_USER=ss_cfg('SKILLSNAP_DB_USER','');
$DB_PASS=ss_cfg('SKILLSNAP_DB_PASS','');
$ADMIN_HASH=ss_cfg('SKILLSNAP_ADMIN_PASSWORD_HASH','');
$ADMIN_PASSWORD=ss_cfg('SKILLSNAP_ADMIN_PASSWORD','');
$OPENAI_KEY=ss_cfg('SKILLSNAP_OPENAI_API_KEY','');
$OPENAI_MODEL=ss_cfg('SKILLSNAP_OPENAI_MODEL','gpt-4.1-mini');
$UPLOAD_DIR=ss_cfg('SKILLSNAP_UPLOAD_DIR',dirname(__DIR__).'/uploads');
if($DB_NAME===''||$DB_USER===''){http_response_code(500);exit('Configure SkillSnap first: copy config.local.example.php to config.local.php.');}

function ss_db(){ static $pdo; global $DB_HOST,$DB_NAME,$DB_USER,$DB_PASS; if($pdo)return $pdo; $pdo=new PDO("mysql:host=$DB_HOST;dbname=$DB_NAME;charset=utf8mb4",$DB_USER,$DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); return $pdo; }
function ss_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ss_post($k,$d=''){return isset($_POST[$k])?trim((string)$_POST[$k]):$d;}
function ss_get($k,$d=''){return isset($_GET[$k])?trim((string)$_GET[$k]):$d;}
function ss_json($x,$status=200){http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function ss_now(){return date('Y-m-d H:i:s');}
function ss_norm($s){$s=mb_strtolower(trim(preg_replace('/\s+/u',' ',(string)$s)),'UTF-8');$s=preg_replace('/[^\pL\pN+#.\/ -]+/u',' ',$s);return trim(preg_replace('/\s+/u',' ',$s));}
function ss_decode($s){$j=json_decode((string)$s,true);return is_array($j)?$j:[];}
function ss_https(){return(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https';}

function ss_schema(){
 $p=ss_db();
 $p->exec("CREATE TABLE IF NOT EXISTS skillsnap_candidates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(255) NOT NULL,email VARCHAR(255),phone VARCHAR(80),current_role VARCHAR(255),target_role VARCHAR(255),target_location VARCHAR(255),current_ctc VARCHAR(100),expected_ctc VARCHAR(100),notice_period VARCHAR(100),stage VARCHAR(80) NOT NULL DEFAULT 'Lead',status VARCHAR(40) NOT NULL DEFAULT 'Active',notes MEDIUMTEXT,resume_original_name VARCHAR(512),resume_stored_name VARCHAR(512),resume_mime VARCHAR(120),resume_text LONGTEXT,requirements_json LONGTEXT,analysis_version INT NOT NULL DEFAULT 0,share_token VARCHAR(96),share_enabled TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_ss_share(share_token),INDEX idx_ss_name(full_name),INDEX idx_ss_target(target_role)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $p->exec("CREATE TABLE IF NOT EXISTS skillsnap_candidate_requirements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,candidate_id BIGINT UNSIGNED NOT NULL,group_name ENUM('skills','experience','projects','certificates') NOT NULL,term VARCHAR(700) NOT NULL,term_norm VARCHAR(700) NOT NULL,description MEDIUMTEXT,weight DECIMAL(12,4) NOT NULL DEFAULT 1,mentions INT NOT NULL DEFAULT 1,auto_status ENUM('existing','missing') NOT NULL DEFAULT 'missing',ai_status ENUM('existing','partial','missing'),ai_confidence DECIMAL(5,4),ai_reason MEDIUMTEXT,ai_evidence MEDIUMTEXT,review_status ENUM('existing','partial','missing','not_required'),evidence MEDIUMTEXT,reviewer_note MEDIUMTEXT,updated_at DATETIME NOT NULL,UNIQUE KEY uq_ss_req(candidate_id,group_name,term_norm),CONSTRAINT fk_ss_req_candidate FOREIGN KEY(candidate_id) REFERENCES skillsnap_candidates(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $p->exec("CREATE TABLE IF NOT EXISTS skillsnap_activity(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,candidate_id BIGINT UNSIGNED NOT NULL,action_name VARCHAR(120) NOT NULL,detail MEDIUMTEXT,created_at DATETIME NOT NULL,INDEX idx_ss_activity(candidate_id,created_at),CONSTRAINT fk_ss_activity_candidate FOREIGN KEY(candidate_id) REFERENCES skillsnap_candidates(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $p->exec("CREATE TABLE IF NOT EXISTS skillsnap_job_details(ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,Title VARCHAR(512),Company VARCHAR(255),Location VARCHAR(255),parsed_json LONGTEXT,skill_desc LONGTEXT,analysed TINYINT(1) NOT NULL DEFAULT 0,apply_url TEXT,created_at DATETIME,INDEX idx_ss_job_title(Title),INDEX idx_ss_job_company(Company),INDEX idx_ss_job_analysed(analysed)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
ss_schema();
function ss_log($id,$a,$d=''){ss_db()->prepare('INSERT INTO skillsnap_activity(candidate_id,action_name,detail,created_at) VALUES(?,?,?,?)')->execute([$id,$a,$d,ss_now()]);}

session_name('skillsnap_admin');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>ss_https(),'httponly'=>true,'samesite'=>'Lax']);
session_start();
function ss_password_ok($p){global $ADMIN_HASH,$ADMIN_PASSWORD;if($ADMIN_HASH!=='')return password_verify($p,$ADMIN_HASH);return $ADMIN_PASSWORD!==''&&hash_equals($ADMIN_PASSWORD,$p);}
function ss_public_action(){if(ss_get('share')!=='')return true;return in_array(ss_get('action'),['public_get','public_requirement_update'],true);}
if(ss_get('action')==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){if(ss_password_ok(ss_post('password'))){session_regenerate_id(true);$_SESSION['skillsnap_admin']=1;header('Location: '.strtok($_SERVER['REQUEST_URI'],'?'));exit;}$loginError='Password not accepted.';}
if(ss_get('action')==='logout'){$_SESSION=[];session_destroy();header('Location: '.strtok($_SERVER['REQUEST_URI'],'?'));exit;}
if(!ss_public_action()&&empty($_SESSION['skillsnap_admin'])){
 echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkillSnap</title><style>body{font:15px system-ui;background:#f5f7fb;display:grid;place-items:center;min-height:100vh}.box{width:min(420px,90vw);background:white;padding:28px;border-radius:18px;box-shadow:0 20px 50px #0f172a22}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:10px;border-radius:10px;border:1px solid #cbd5e1}button{background:#2563eb;color:white;font-weight:800;border:0}</style></head><body><form class="box" method="post" action="?action=login"><h1>SkillSnap</h1><p>Private intern test workspace</p>'.(!empty($loginError)?'<p style="color:#b91c1c">'.ss_h($loginError).'</p>':'').'<input type="password" name="password" placeholder="Admin password" required><button>Continue</button></form></body></html>';exit;
}
if(session_status()===PHP_SESSION_ACTIVE)session_write_close();

function ss_extract_resume($path,$ext){
 $ext=strtolower($ext);
 if($ext==='txt')return trim((string)file_get_contents($path));
 if($ext==='docx'){$z=new ZipArchive();if($z->open($path)!==true)throw new RuntimeException('Cannot open DOCX.');$xml=$z->getFromName('word/document.xml');$z->close();if($xml===false)throw new RuntimeException('DOCX document.xml missing.');$xml=preg_replace('/<w:tab\/>/','\t',$xml);$xml=preg_replace('/<w:br\/>/','\n',$xml);$xml=preg_replace('/<\/w:p>/','\n',$xml);return trim(html_entity_decode(strip_tags($xml),ENT_QUOTES|ENT_XML1,'UTF-8'));}
 if($ext==='pdf'){$bin=trim((string)@shell_exec('command -v pdftotext 2>/dev/null'));if($bin!==''){$out=@shell_exec(escapeshellarg($bin).' -layout '.escapeshellarg($path).' - 2>/dev/null');if(trim((string)$out)!=='')return trim($out);}if(class_exists('\\Smalot\\PdfParser\\Parser')){$parser=new \Smalot\PdfParser\Parser();return trim((string)$parser->parseFile($path)->getText());}throw new RuntimeException('PDF extraction needs pdftotext or smalot/pdfparser.');}
 throw new RuntimeException('Only PDF, DOCX and TXT are supported.');
}
function ss_group_items($json,$group){$j=is_array($json)?$json:ss_decode($json);$keys=[$group];if($group==='certificates')$keys[]='certifications';$items=[];foreach($keys as $k){if(isset($j[$k])&&is_array($j[$k])){$items=$j[$k];break;}}$out=[];foreach($items as $it){if(is_string($it)){$t=trim($it);$w=1;}elseif(is_array($it)){$t=trim((string)($it['term']??$it['name']??$it['title']??''));$w=is_numeric($it['weight']??null)?(float)$it['weight']:1;}else continue;if($t!=='')$out[]=['term'=>$t,'weight'=>$w];}return $out;}
function ss_desc_map($json,$group){$j=is_array($json)?$json:ss_decode($json);$items=$j[$group]??[];$out=[];if(!is_array($items))return $out;foreach($items as $it){if(!is_array($it))continue;$t=trim((string)($it['term']??''));if($t!=='')$out[ss_norm($t)]=trim((string)($it['desc']??''));}return $out;}
function ss_role_requirements($role,$location=''){$role=trim($role);$agg=['skills'=>[],'experience'=>[],'projects'=>[],'certificates'=>[]];if($role==='')return ['groups'=>$agg,'jobs_scanned'=>0];$sql="SELECT Title,Company,Location,parsed_json,skill_desc FROM skillsnap_job_details WHERE analysed=1 AND (Title LIKE ? OR parsed_json LIKE ?)";$args=['%'.$role.'%','%'.$role.'%'];if($location!==''){$sql.=' AND Location LIKE ?';$args[]='%'.$location.'%';}$sql.=' ORDER BY ID DESC LIMIT 5000';$st=ss_db()->prepare($sql);$st->execute($args);$n=0;while($r=$st->fetch()){$n++;$pj=ss_decode($r['parsed_json']);$sd=ss_decode($r['skill_desc']);foreach(array_keys($agg) as $g){$desc=ss_desc_map($sd,$g);$seen=[];foreach(ss_group_items($pj,$g) as $it){$k=ss_norm($it['term']);if($k===''||isset($seen[$k]))continue;$seen[$k]=1;if(!isset($agg[$g][$k]))$agg[$g][$k]=['term'=>$it['term'],'description'=>$desc[$k]??'','weight'=>0,'mentions'=>0];$agg[$g][$k]['weight']+=(float)$it['weight'];$agg[$g][$k]['mentions']++;}}}foreach($agg as $g=>$map){$rows=array_values($map);usort($rows,fn($a,$b)=>($b['weight']<=>$a['weight'])?:($b['mentions']<=>$a['mentions']));$agg[$g]=array_slice($rows,0,30);}return ['groups'=>$agg,'jobs_scanned'=>$n];}
function ss_match($resume,$term){$hay=' '.ss_norm($resume).' ';$needle=ss_norm($term);$aliases=['amazon web services'=>['aws'],'google cloud platform'=>['gcp'],'machine learning'=>['ml'],'artificial intelligence'=>['ai'],'large language model'=>['llm','llms'],'javascript'=>['js'],'typescript'=>['ts']];$terms=[$needle];foreach($aliases as $root=>$xs)if(str_contains($needle,$root)||in_array($needle,$xs,true))$terms=array_merge($terms,$xs);foreach(array_unique($terms) as $x)if($x!==''&&mb_strpos($hay,$x)!==false)return ['status'=>'existing','evidence'=>'Keyword/evidence found in resume.'];return ['status'=>'missing','evidence'=>''];}
function ss_analyze($cid){$p=ss_db();$st=$p->prepare('SELECT * FROM skillsnap_candidates WHERE id=?');$st->execute([$cid]);$c=$st->fetch();if(!$c)throw new RuntimeException('Candidate not found.');if(trim($c['target_role'])==='')throw new RuntimeException('Target role is required.');if(trim((string)$c['resume_text'])==='')throw new RuntimeException('Upload a readable resume first.');$req=ss_role_requirements($c['target_role'],$c['target_location']);$up=$p->prepare("INSERT INTO skillsnap_candidate_requirements(candidate_id,group_name,term,term_norm,description,weight,mentions,auto_status,evidence,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE term=VALUES(term),description=VALUES(description),weight=VALUES(weight),mentions=VALUES(mentions),auto_status=VALUES(auto_status),evidence=IF(review_status IS NULL,VALUES(evidence),evidence),updated_at=VALUES(updated_at)");$active=[];foreach($req['groups'] as $g=>$rows)foreach($rows as $r){$m=ss_match($c['resume_text'],$r['term']);$k=ss_norm($r['term']);$active[$g][$k]=1;$up->execute([$cid,$g,$r['term'],$k,$r['description'],$r['weight'],$r['mentions'],$m['status'],$m['evidence'],ss_now()]);}foreach(['skills','experience','projects','certificates'] as $g){$keys=array_keys($active[$g]??[]);if($keys){$marks=implode(',',array_fill(0,count($keys),'?'));$p->prepare("DELETE FROM skillsnap_candidate_requirements WHERE candidate_id=? AND group_name=? AND term_norm NOT IN ($marks)")->execute(array_merge([$cid,$g],$keys));}else $p->prepare('DELETE FROM skillsnap_candidate_requirements WHERE candidate_id=? AND group_name=?')->execute([$cid,$g]);}$snap=json_encode(['role'=>$c['target_role'],'location'=>$c['target_location'],'jobs_scanned'=>$req['jobs_scanned'],'generated_at'=>ss_now()],JSON_UNESCAPED_SLASHES);$p->prepare('UPDATE skillsnap_candidates SET requirements_json=?,analysis_version=analysis_version+1,updated_at=? WHERE id=?')->execute([$snap,ss_now(),$cid]);ss_log($cid,'analysis_completed','Jobs scanned: '.$req['jobs_scanned']);return ss_payload($cid);}
function ss_payload($cid){$st=ss_db()->prepare('SELECT * FROM skillsnap_candidates WHERE id=?');$st->execute([$cid]);$c=$st->fetch();if(!$c)return null;$st=ss_db()->prepare("SELECT *,COALESCE(review_status,ai_status,auto_status) final_status FROM skillsnap_candidate_requirements WHERE candidate_id=? ORDER BY FIELD(group_name,'skills','experience','projects','certificates'),weight DESC,mentions DESC");$st->execute([$cid]);$groups=['skills'=>[],'experience'=>[],'projects'=>[],'certificates'=>[]];$counts=['existing'=>0,'partial'=>0,'missing'=>0,'not_required'=>0,'total'=>0];while($r=$st->fetch()){$groups[$r['group_name']][]=$r;$s=$r['final_status'];if(isset($counts[$s]))$counts[$s]++;$counts['total']++;}$den=max(1,$counts['total']-$counts['not_required']);$match=round(($counts['existing']+$counts['partial']*.5)/$den*100,1);unset($c['resume_text'],$c['resume_stored_name']);return ['candidate'=>$c,'groups'=>$groups,'counts'=>$counts,'match_percent'=>$match];}
function ss_public_payload($token){$st=ss_db()->prepare('SELECT id FROM skillsnap_candidates WHERE share_token=? AND share_enabled=1');$st->execute([$token]);$id=(int)$st->fetchColumn();return $id?ss_payload($id):null;}
function ss_company_matches($cid){$c=ss_db()->prepare('SELECT * FROM skillsnap_candidates WHERE id=?');$c->execute([$cid]);$c=$c->fetch();if(!$c)return [];$corpus=ss_norm(($c['resume_text']??'').' '.($c['current_role']??'').' '.($c['target_role']??''));$st=ss_db()->query("SELECT ID,Title,Company,Location,parsed_json,apply_url FROM skillsnap_job_details WHERE analysed=1 ORDER BY ID DESC LIMIT 300");$out=[];while($r=$st->fetch()){$pj=ss_decode($r['parsed_json']);$weights=['skills'=>.4,'experience'=>.3,'projects'=>.2,'certificates'=>.1];$earned=0;$active=0;$parts=[];foreach($weights as $g=>$w){$items=ss_group_items($pj,$g);if(!$items)continue;$active+=$w;$hits=0;foreach($items as $it)if(ss_match($corpus,$it['term'])['status']==='existing')$hits++;$score=count($items)?$hits/count($items)*100:0;$earned+=$w*$score;$parts[$g]=round($score,1);}if($active>0)$out[]=['job_id'=>$r['ID'],'title'=>$r['Title'],'company'=>$r['Company'],'location'=>$r['Location'],'apply_url'=>$r['apply_url'],'score'=>round($earned/$active,1),'groups'=>$parts];}usort($out,fn($a,$b)=>$b['score']<=>$a['score']);return array_slice($out,0,50);}

$action=ss_get('action');
try{
 if($action==='candidate_list'){$q=ss_get('q');$sql='SELECT id,full_name,email,phone,current_role,target_role,target_location,stage,status,created_at,updated_at FROM skillsnap_candidates WHERE 1';$args=[];if($q!==''){$sql.=' AND (full_name LIKE ? OR email LIKE ? OR phone LIKE ? OR target_role LIKE ?)';$x='%'.$q.'%';$args=[$x,$x,$x,$x];}$sql.=' ORDER BY updated_at DESC LIMIT 500';$st=ss_db()->prepare($sql);$st->execute($args);ss_json(['ok'=>1,'rows'=>$st->fetchAll()]);}
 if($action==='candidate_get'){if(!$p=ss_payload((int)ss_get('id')))ss_json(['error'=>'Candidate not found'],404);ss_json(['ok'=>1]+$p);}
 if($action==='candidate_save'){$id=(int)ss_post('id');$fields=['full_name','email','phone','current_role','target_role','target_location','current_ctc','expected_ctc','notice_period','stage','status','notes'];$v=[];foreach($fields as $f)$v[$f]=ss_post($f);if($v['full_name']==='')ss_json(['error'=>'Candidate name required'],422);if($id){$set=implode(',',array_map(fn($x)=>"`$x`=?",$fields));ss_db()->prepare("UPDATE skillsnap_candidates SET $set,updated_at=? WHERE id=?")->execute([...array_values($v),ss_now(),$id]);ss_log($id,'candidate_updated');}else{$cols=implode(',',array_map(fn($x)=>"`$x`",$fields));$marks=implode(',',array_fill(0,count($fields),'?'));ss_db()->prepare("INSERT INTO skillsnap_candidates($cols,created_at,updated_at) VALUES($marks,?,?)")->execute([...array_values($v),ss_now(),ss_now()]);$id=(int)ss_db()->lastInsertId();ss_log($id,'candidate_created');}ss_json(['ok'=>1,'payload'=>ss_payload($id)]);}
 if($action==='candidate_delete'){$id=(int)ss_post('id');global $UPLOAD_DIR;$st=ss_db()->prepare('SELECT resume_stored_name FROM skillsnap_candidates WHERE id=?');$st->execute([$id]);$f=$st->fetchColumn();if($f&&is_file($UPLOAD_DIR.'/'.$f))@unlink($UPLOAD_DIR.'/'.$f);ss_db()->prepare('DELETE FROM skillsnap_candidates WHERE id=?')->execute([$id]);ss_json(['ok'=>1]);}
 if($action==='resume_upload'){$id=(int)ss_post('candidate_id');if(!$id||!isset($_FILES['resume'])||$_FILES['resume']['error']!==UPLOAD_ERR_OK)ss_json(['error'=>'Resume upload failed'],422);if($_FILES['resume']['size']>10*1024*1024)ss_json(['error'=>'Resume exceeds 10 MB'],422);$orig=basename($_FILES['resume']['name']);$ext=strtolower(pathinfo($orig,PATHINFO_EXTENSION));if(!in_array($ext,['pdf','docx','txt'],true))ss_json(['error'=>'Only PDF, DOCX and TXT'],422);if(!is_dir($UPLOAD_DIR))mkdir($UPLOAD_DIR,0750,true);$stored='skillsnap_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$ext;$dest=$UPLOAD_DIR.'/'.$stored;if(!move_uploaded_file($_FILES['resume']['tmp_name'],$dest))throw new RuntimeException('Could not store resume.');$text=ss_extract_resume($dest,$ext);$st=ss_db()->prepare('SELECT resume_stored_name FROM skillsnap_candidates WHERE id=?');$st->execute([$id]);$old=$st->fetchColumn();if($old&&is_file($UPLOAD_DIR.'/'.$old))@unlink($UPLOAD_DIR.'/'.$old);$mime=mime_content_type($dest)?:'application/octet-stream';ss_db()->prepare('UPDATE skillsnap_candidates SET resume_original_name=?,resume_stored_name=?,resume_mime=?,resume_text=?,updated_at=? WHERE id=?')->execute([$orig,$stored,$mime,$text,ss_now(),$id]);ss_log($id,'resume_uploaded',$orig);$c=ss_db()->prepare('SELECT target_role FROM skillsnap_candidates WHERE id=?');$c->execute([$id]);$payload=trim((string)$c->fetchColumn())!==''?ss_analyze($id):ss_payload($id);ss_json(['ok'=>1,'text_length'=>mb_strlen($text),'payload'=>$payload]);}
 if($action==='analyze'){$id=(int)ss_post('candidate_id');if(ss_post('target_role')!=='')ss_db()->prepare('UPDATE skillsnap_candidates SET target_role=?,target_location=?,updated_at=? WHERE id=?')->execute([ss_post('target_role'),ss_post('target_location'),ss_now(),$id]);ss_json(['ok'=>1,'payload'=>ss_analyze($id)]);}
 if($action==='requirement_update'){$id=(int)ss_post('id');$status=ss_post('review_status');if(!in_array($status,['','existing','partial','missing','not_required'],true))ss_json(['error'=>'Invalid status'],422);$st=ss_db()->prepare('SELECT candidate_id FROM skillsnap_candidate_requirements WHERE id=?');$st->execute([$id]);$cid=(int)$st->fetchColumn();ss_db()->prepare('UPDATE skillsnap_candidate_requirements SET review_status=?,evidence=?,reviewer_note=?,updated_at=? WHERE id=?')->execute([$status===''?null:$status,ss_post('evidence'),ss_post('reviewer_note'),ss_now(),$id]);ss_log($cid,'requirement_reviewed');ss_json(['ok'=>1,'payload'=>ss_payload($cid)]);}
 if($action==='share_create'){$id=(int)ss_post('candidate_id');$st=ss_db()->prepare('SELECT share_token FROM skillsnap_candidates WHERE id=?');$st->execute([$id]);$token=(string)$st->fetchColumn();if($token==='')$token=bin2hex(random_bytes(24));ss_db()->prepare('UPDATE skillsnap_candidates SET share_token=?,share_enabled=1,updated_at=? WHERE id=?')->execute([$token,ss_now(),$id]);$base=(ss_https()?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').strtok($_SERVER['REQUEST_URI'],'?');ss_json(['ok'=>1,'share_url'=>$base.'?share='.rawurlencode($token)]);}
 if($action==='company_matches'){$id=(int)ss_get('candidate_id');ss_json(['ok'=>1,'jobs'=>ss_company_matches($id)]);}
 if($action==='public_requirement_update'){$token=ss_post('token');$id=(int)ss_post('id');$status=ss_post('review_status');$st=ss_db()->prepare('SELECT cr.candidate_id FROM skillsnap_candidate_requirements cr JOIN skillsnap_candidates c ON c.id=cr.candidate_id WHERE cr.id=? AND c.share_token=? AND c.share_enabled=1');$st->execute([$id,$token]);$cid=(int)$st->fetchColumn();if(!$cid)ss_json(['error'=>'Unavailable'],404);ss_db()->prepare('UPDATE skillsnap_candidate_requirements SET review_status=?,evidence=?,reviewer_note=?,updated_at=? WHERE id=?')->execute([$status===''?null:$status,ss_post('evidence'),ss_post('reviewer_note'),ss_now(),$id]);ss_json(['ok'=>1,'payload'=>ss_public_payload($token)]);}
}catch(Throwable $e){ss_json(['error'=>'server_error','message'=>$e->getMessage()],500);}

$share=ss_get('share');
if($share!==''){$p=ss_public_payload($share);if(!$p){http_response_code(404);exit('Shared profile unavailable.');}$c=$p['candidate'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=ss_h($c['full_name'])?> — SkillSnap</title><style>body{margin:0;background:#f8fafc;color:#0f172a;font:14px/1.5 system-ui}.wrap{max-width:1200px;margin:auto;padding:20px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.k{background:#f8fafc;border-radius:12px;padding:12px}.v{font-size:26px;font-weight:900}.req{border-top:1px solid #e2e8f0;padding:10px 0}.tag{display:inline-block;padding:3px 8px;border-radius:999px;background:#eef2ff}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><h1>SkillSnap</h1><div class="card"><h2><?=ss_h($c['full_name'])?></h2><p><?=ss_h($c['current_role'])?> → <b><?=ss_h($c['target_role'])?></b> · <?=ss_h($c['target_location'])?></p></div><div class="grid"><div class="k">Match<div class="v"><?=$p['match_percent']?>%</div></div><div class="k">Existing<div class="v"><?=$p['counts']['existing']?></div></div><div class="k">Partial<div class="v"><?=$p['counts']['partial']?></div></div><div class="k">Missing<div class="v"><?=$p['counts']['missing']?></div></div></div><?php foreach($p['groups'] as $g=>$rows):?><section class="card"><h2><?=ss_h(ucfirst($g))?></h2><?php foreach($rows as $r):?><div class="req"><b><?=ss_h($r['term'])?></b> <span class="tag"><?=ss_h($r['final_status'])?></span><div><?=ss_h($r['evidence']?:$r['ai_evidence'])?></div></div><?php endforeach;?></section><?php endforeach;?></main></body></html><?php exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkillSnap</title><style>body{margin:0;background:#f5f7fb;color:#0f172a;font:14px/1.45 system-ui}header{background:#0f172a;color:#fff;padding:14px 20px}.wrap{max-width:1400px;margin:auto;padding:18px}.layout{display:grid;grid-template-columns:320px 1fr;gap:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:14px}.row{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}input,select,textarea,button{font:inherit;box-sizing:border-box;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:10px}button{background:#2563eb;color:#fff;border:0;font-weight:800;cursor:pointer}.ghost{background:#fff;color:#0f172a;border:1px solid #cbd5e1}.candidate{padding:10px;border-bottom:1px solid #e2e8f0;cursor:pointer}.candidate:hover{background:#eff6ff}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.kpi{background:#f8fafc;border-radius:12px;padding:10px}.kpi b{font-size:24px}.req{border:1px solid #e2e8f0;border-radius:12px;padding:10px;margin:8px 0}.req select{width:auto}.hidden{display:none}@media(max-width:900px){.layout{grid-template-columns:1fr}.row,.kpis{grid-template-columns:1fr 1fr}}</style></head><body><header><b>SkillSnap</b> · Isolated Intern Test Workspace <a href="?action=logout" style="float:right;color:white">Logout</a></header><main class="wrap"><div class="layout"><aside class="card"><div class="row"><input id="search" placeholder="Search"><button id="new">New</button></div><div id="list"></div></aside><section><div id="empty" class="card">Select or create a candidate.</div><div id="work" class="hidden"><div class="card"><div class="row"><input id="name" placeholder="Full name"><input id="email" placeholder="Email"><input id="phone" placeholder="Phone"><input id="current_role" placeholder="Current role"><input id="target_role" placeholder="Target role"><input id="target_location" placeholder="Target location"><input id="current_ctc" placeholder="Current CTC"><input id="expected_ctc" placeholder="Expected CTC"><input id="notice_period" placeholder="Notice period"><select id="stage"><option>Lead</option><option>Qualified</option><option>Proposal</option><option>Enrolled</option></select></div><textarea id="notes" placeholder="Notes"></textarea><div class="row"><button id="save">Save Candidate</button><button id="delete" class="ghost">Delete</button></div></div><div class="card"><h3>Resume & Analysis</h3><input type="file" id="resume" accept=".pdf,.docx,.txt"><div class="row"><button id="upload">Upload Resume</button><button id="analyze">Analyze Target Role</button></div></div><div class="kpis"><div class="kpi">Match<br><b id="match">0%</b></div><div class="kpi">Existing<br><b id="ex">0</b></div><div class="kpi">Partial<br><b id="pa">0</b></div><div class="kpi">Missing<br><b id="mi">0</b></div></div><div class="card"><div class="row"><button id="share">Create Share Link</button><button id="jobs">Find Matching Jobs</button></div><div id="shareOut"></div><div id="jobOut"></div></div><div id="requirements"></div></div></section></div></main><script>
const $=id=>document.getElementById(id);let current=0,payload=null;const fields=['name','email','phone','current_role','target_role','target_location','current_ctc','expected_ctc','notice_period','stage','notes'];
async function req(action,opt={}){const r=await fetch('?action='+action,opt);const j=await r.json();if(!r.ok||j.error)throw new Error(j.message||j.error);return j}
async function loadList(){const j=await req('candidate_list&q='+encodeURIComponent($('search').value));$('list').innerHTML=j.rows.map(x=>`<div class="candidate" data-id="${x.id}"><b>${esc(x.full_name)}</b><br><small>${esc(x.target_role||x.current_role||'')}</small></div>`).join('');document.querySelectorAll('.candidate').forEach(x=>x.onclick=()=>openCandidate(x.dataset.id))}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
async function openCandidate(id){const j=await req('candidate_get&id='+id);current=Number(id);payload=j;render()}
function render(){const c=payload.candidate;$('empty').classList.add('hidden');$('work').classList.remove('hidden');$('name').value=c.full_name||'';['email','phone','current_role','target_role','target_location','current_ctc','expected_ctc','notice_period','stage','notes'].forEach(f=>$(f).value=c[f]||'');$('match').textContent=payload.match_percent+'%';$('ex').textContent=payload.counts.existing;$('pa').textContent=payload.counts.partial;$('mi').textContent=payload.counts.missing;$('requirements').innerHTML=Object.entries(payload.groups).map(([g,rows])=>`<div class="card"><h3>${esc(g)}</h3>${rows.map(r=>`<div class="req"><b>${esc(r.term)}</b><br><small>${esc(r.description||'')}</small><select data-rid="${r.id}"><option value="" ${!r.review_status?'selected':''}>Automatic: ${esc(r.ai_status||r.auto_status)}</option><option value="existing" ${r.review_status==='existing'?'selected':''}>Existing</option><option value="partial" ${r.review_status==='partial'?'selected':''}>Partial</option><option value="missing" ${r.review_status==='missing'?'selected':''}>Missing</option><option value="not_required" ${r.review_status==='not_required'?'selected':''}>Not required</option></select><div>${esc(r.evidence||r.ai_evidence||'')}</div></div>`).join('')}</div>`).join('');document.querySelectorAll('[data-rid]').forEach(s=>s.onchange=async()=>{const fd=new FormData();fd.append('id',s.dataset.rid);fd.append('review_status',s.value);fd.append('evidence','');fd.append('reviewer_note','');const j=await req('requirement_update',{method:'POST',body:fd});payload=j.payload;render()})}
$('new').onclick=()=>{current=0;payload={candidate:{full_name:'',stage:'Lead',status:'Active'},counts:{existing:0,partial:0,missing:0},groups:{skills:[],experience:[],projects:[],certificates:[]},match_percent:0};render()};$('search').oninput=()=>{clearTimeout(window.t);window.t=setTimeout(loadList,250)};
$('save').onclick=async()=>{const fd=new FormData();fd.append('id',current);fd.append('full_name',$('name').value);['email','phone','current_role','target_role','target_location','current_ctc','expected_ctc','notice_period','stage','notes'].forEach(f=>fd.append(f,$(f).value));fd.append('status','Active');const j=await req('candidate_save',{method:'POST',body:fd});payload=j.payload;current=payload.candidate.id;render();loadList()};
$('delete').onclick=async()=>{if(!current||!confirm('Delete this SkillSnap candidate?'))return;const fd=new FormData();fd.append('id',current);await req('candidate_delete',{method:'POST',body:fd});location.reload()};
$('upload').onclick=async()=>{if(!current)return alert('Save candidate first.');if(!$('resume').files[0])return alert('Choose a resume.');const fd=new FormData();fd.append('candidate_id',current);fd.append('resume',$('resume').files[0]);const j=await req('resume_upload',{method:'POST',body:fd});payload=j.payload;render()};
$('analyze').onclick=async()=>{if(!current)return;const fd=new FormData();fd.append('candidate_id',current);fd.append('target_role',$('target_role').value);fd.append('target_location',$('target_location').value);const j=await req('analyze',{method:'POST',body:fd});payload=j.payload;render()};
$('share').onclick=async()=>{const fd=new FormData();fd.append('candidate_id',current);const j=await req('share_create',{method:'POST',body:fd});$('shareOut').innerHTML=`<p><a target="_blank" href="${esc(j.share_url)}">${esc(j.share_url)}</a></p>`};
$('jobs').onclick=async()=>{const j=await req('company_matches&candidate_id='+current);$('jobOut').innerHTML='<h3>Top Job Matches</h3>'+j.jobs.slice(0,10).map(x=>`<div class="req"><b>${esc(x.company)} — ${esc(x.title)}</b> · ${x.score}%<br><small>${esc(x.location)}</small>${x.apply_url?` · <a target="_blank" href="${esc(x.apply_url)}">Apply</a>`:''}</div>`).join('')};loadList();
</script></body></html>
